Skip to content 目前调查到的原因：Boss网站会检测到程序驱动浏览器时，会将页面回退，导致页面看起来"被关闭"了，我尝试过的方式是，即使手动打开PlayWright浏览器，也不会受到检测，，但是不论是程序驱动，还是使用CDP远程端口的方式，都会被检测到并关闭页面，不知道有哪位仁兄可以定位出检测的逻辑或者是有什么有效的方法可以规避，都可以在这里讨论 Upvote LZ好，我是 GeekGeekRun - 牛人快跑 的维护者 看来咱们是竞品哦~ 不过我不是来做宣传的，只是来探讨下。这个问题我也遇到了 🥴 这是之前在L站上，解决了这个问题后，我和佬友的一些交流 https://linux.do/t/topic/640626/223?u=geekgeekrun 网站对抗 DevTools / 自动化RPA 的原理 function checkDevTools() { const aLargeObjectOrArray = [{}] // 一个很大的、控制台打印时需要处理很长时间的对象 let printStartTime = new Date() console.table(aLargeObjectOrArray) // 某个在控制台开启情况下会特别耗时的动作 let printEndTime = new Date() // 判断打印前后，时间差是否大于某个值（可能是个经验值）- 控制台未打开的情况下，打印日志应当是不耗时的 // 如果打印所耗费时间过长，就认为控制台打开了 if (printEndTime - printStartTime > 50) { return true } // 否则正常执行 return false
} 实际代码比上方代码复杂，见 https://github.com/theajack/disable-devtool - 这个库甚至判断了vConsole 我大概说下我的解决步骤 解决步骤 页面加载前，把console相关函数覆盖为空函数 主要用到的Puppeteer的API是： https://pptr.dev/api/puppeteer.page.evaluateonnewdocument 对应到Playwright的API似乎是： https://playwright.dev/java/docs/api/class-page#page-add-init-script 把要执行的函数，通过这两个API传进去 因此需要在页面中执行类似 console.log = () => {} 这样的函数 函数被覆盖后，不能让对方网站检测到我们覆盖了相关函数 步骤1中我们覆盖了页面中的原生方法console.log，但这个覆盖是可以被轻松检测的；对方网站可以执行： console.log.toString() 或 Function.prototype.toString.call(console.log) 来检测函数是不是被我们覆盖掉的。（我看了下Boss直聘代码， 会上报有关“函数是否被覆盖”的数据埋点 ） console.log 没有被覆盖掉的情况下，如上代码执行后返回值为 function log() { [native code] } 被覆盖掉的情况下（假设是按步骤1覆盖的），如上代码执行后返回值为 () => {} 一般的检测逻辑是检查返回值中是否包含 [native code] 为此需要覆盖函数原型上的 原生方法 Function.prototype.toString ，来防止对方网站判断。需要做的大致逻辑： const originFunctionPrototypeToString = Function.prototype.toString
Function.prototype.toString = function toString(...args) { if (this === console.log) { return `function log() { [native code] }` } else { return originFunctionPrototypeToString.apply(this, args) }
} 同样，我们也要避免“覆盖函数原型上的 原生方法 Function.prototype.toString ”这个动作被对方网站发现 - 因为对方网站可以再执行： Function.prototype.toString.toString() 或 Function.prototype.toString.call(Function.prototype.toString) 来检测函数是不是被我们覆盖掉的。因此需要进一步处理。 最终完整的需要在页面初始化时即执行的函数 下方代码是AI生成的，考虑得更完整一些 () => { (() => { "use strict"; /* ------------------------------------------------------- * 1. 保存原生 Function.prototype.toString * ----------------------------------------------------- */ const nativeFunctionToString = Function.prototype.toString; /* ------------------------------------------------------- * 2. WeakMap：函数 → 伪原生源码 * ----------------------------------------------------- */ const nativeSourceMap = new WeakMap(); /* ------------------------------------------------------- * 3. 注册伪原生源码 * ----------------------------------------------------- */ const registerNativeSource = (fn, source) => { try { nativeSourceMap.set(fn, source); } catch (_) {} }; /* ------------------------------------------------------- * 4. 劫持 Function.prototype.toString * ----------------------------------------------------- */ Object.defineProperty(Function.prototype, "toString", { configurable: true, writable: true, value: function toString() { if (nativeSourceMap.has(this)) { return nativeSourceMap.get(this); } return nativeFunctionToString.call(this); }, }); /* ------------------------------------------------------- * 5. 伪装 Function.prototype.toString 自身 * ----------------------------------------------------- */ registerNativeSource( Function.prototype.toString, nativeFunctionToString.toString(), ); /* ------------------------------------------------------- * 6. stealthify：包装函数但保持“原生外观” * ----------------------------------------------------- */ const stealthify = (obj, prop, handler) => { const original = obj[prop]; if (typeof original !== "function") return; const wrapped = function (...args) { return handler.call(this, original, args); }; const namePropertyDescriptor = Object.getOwnPropertyDescriptor( wrapped, "name", ); // 处理函数 name 属性 Object.defineProperty(wrapped, "name", { ...namePropertyDescriptor, value: prop, }); // 保留 prototype（某些函数有） try { Object.setPrototypeOf(wrapped, Object.getPrototypeOf(original)); } catch (_) {} // 注册伪原生源码（直接复用原函数的 native 表现） registerNativeSource(wrapped, nativeFunctionToString.call(original)); // 用 defineProperty 保持 descriptor 接近原生 const desc = Object.getOwnPropertyDescriptor(obj, prop); Object.defineProperty(obj, prop, { ...desc, value: wrapped, }); }; /* ------------------------------------------------------- * 7. 示例：stealth console.log / debug / info * ----------------------------------------------------- */ const filterConsoleArgs = (args) => args.map((arg) => { if (arg && typeof arg === "object") { // 防止 getter / Proxy / 大对象触发 return {}; } return arg; }); ["log", "debug", "info", "warn", "error", "dir", "table", "debug"].forEach( (name) => { stealthify(console, name, (original, args) => { // ❗不传递原始对象，避免 DevTools / CDP 展开 return original.apply(console, filterConsoleArgs(args)); }); }, ); /* ------------------------------------------------------- * 8. 防御性补丁（可选但强烈建议） * ----------------------------------------------------- */ // 防止检测 toString 被替换 registerNativeSource( registerNativeSource, "function registerNativeSource() { [native code] }", ); })();
} 经过如上处理，网站应该就跳不走了 BTW 我有注意到其它竞品 - 一键职达（macOS版本），没有受此影响（但用户主动开启DevTools依然会跳走），而且使用过程中会弹出程序请求自动控制的权限 因此我怀疑： 通过“打印日志检测时间差来判断浏览器是否开启DevTools/是否正在被自动化控制”，仅适用于基于CDP实现的自动化 - 一旦产生CDP会话，console里的内容就一定会被处理，从而产生处理时间上的开销，导致被检测到 一键职达（macOS版本）是通过macOS相关API或功能实现的浏览器自动化，而非我们使用的基于CDP实现（由Puppeteer/Playwright封装）的自动化 Upvote 4 replies 已解决首页打不开的问题，非常感谢，但是紧接着就碰到了投递岗位的时候，打开岗位页面，就会触发不断的刷新，主要我不知道这是通过什么机制去判断以及触发的，所以不知道怎么解决，你有碰到类似的问题吗？ QQ群都满了？ 已解决首页打不开的问题，非常感谢，但是紧接着就碰到了投递岗位的时候，打开岗位页面，就会触发不断的刷新，主要我不知道这是通过什么机制去判断以及触发的，所以不知道怎么解决，你有碰到类似的问题吗？ https://github.com/Ocyss/boss-helper 这个插件我用着没有碰到过，或许可以参考这个项目怎么解决的呢，因为对前端不是特别深入，所以只是类似推荐给你看下。 大佬，收徒吗 You can't vote on a locked discussion 1 reply 404 我是 AntiDebug_Breaker 插件的作者，实际上核心解决方案并没有多复杂，主要是解决两个方法即可： console.table performance.now 在之前我写过一篇文章： JS逆向系列-无感绕过一类运行时间差反调试 ，在这篇文章中我详细讲述了为什么要hook掉console.table，而hook performance.now的原因实际上是因为boss增强了 disable-devtool 这个库的检测机制，没错，boss采用的就是这个库的反调试。 当然了，boss不止增强了这一处的检测机制，但在这里我也并不想多说其他增强点，我主要是来分享解决方案的，下面是可使用油猴注入的版本： // ==UserScript==
// @name AntiAnti Hook
// @namespace https://github.com/0xsdeo/Hook_JS
// @version 0.2
// @description 反Hook检测
// @author 0xsdeo
// @match *://*/*
// @run-at document-start
// @icon data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==
// @grant none
// ==/UserScript== (function () { 'use strict'; // 必须返回随时间递增的值，否则会被时序检测（t1===t2）判定为 hook 并触发内存炸弹 const navStart = (typeof performance !== 'undefined' && performance.timing) ? performance.timing.navigationStart : Date.now(); console.table = function () {}; performance.now = function () { return Date.now() - navStart; }; const methods = ['console.table', 'performance.now']; function initAntiAntiHook() { try { const hookedFunctions = new Map(); for (let methodPath of methods) { let ref = window; let parts = methodPath.split('.'); try { for (let i = 0; i < parts.length - 1; i++) { ref = ref[parts[i]]; if (!ref) break; } if (ref) { const fn = ref[parts[parts.length - 1]]; if (typeof fn === 'function') { hookedFunctions.set(fn, parts[parts.length - 1]); } } } catch (e) {} } if (hookedFunctions.size === 0) return; let temp_toString = Function.prototype.toString; Function.prototype.toString = function () { if (this === Function.prototype.toString) { return 'function toString() { [native code] }'; } else if (this === Function.prototype.constructor && hookedFunctions.has(Function.prototype.constructor)) { return 'function Function() { [native code] }'; } else if (hookedFunctions.has(this)) { const funcName = hookedFunctions.get(this); return `function ${funcName}() { [native code] }`; } return temp_toString.apply(this, arguments); }; const hookedMethodNames = new Map(); methods.forEach(path => { let ref = window; let parts = path.split('.'); try { for (let i = 0; i < parts.length - 1; i++) { ref = ref[parts[i]]; if (!ref) break; } if (ref) { const fn = ref[parts[parts.length - 1]]; if (typeof fn === 'function') { hookedMethodNames.set(path, fn); } } } catch (e) {} }); const objectHooksMap = new Map(); methods.forEach(path => { const parts = path.split('.'); const rootParts = parts[0] === 'window' ? parts.slice(1) : parts; if (rootParts.length < 2) return; const rootName = rootParts[0]; const remaining = rootParts.slice(1); const fn = hookedMethodNames.get(path); if (!fn) return; if (!objectHooksMap.has(rootName)) objectHooksMap.set(rootName, []); objectHooksMap.get(rootName).push({ remaining, fn }); }); if (!objectHooksMap.has('Function')) objectHooksMap.set('Function', []); const existsToString = objectHooksMap.get('Function') .some(({ remaining }) => remaining.join('.') === 'prototype.toString'); if (!existsToString) { objectHooksMap.get('Function').push({ remaining: ['prototype', 'toString'], fn: Function.prototype.toString }); } let property_accessor = Object.getOwnPropertyDescriptor(HTMLIFrameElement.prototype, "contentWindow"); let get_accessor = property_accessor.get; Object.defineProperty(HTMLIFrameElement.prototype, "contentWindow", { get: function () { let iframe_window = get_accessor.apply(this); iframe_window = new Proxy(iframe_window, { get: function (target, property, receiver) { if (typeof property === 'string') { for (const [fullPath, fn] of hookedMethodNames.entries()) { if (fullPath.endsWith('.' + property) || fullPath === property) { return fn; } } if (objectHooksMap.has(property)) { const obj = Reflect.get(target, property, target); if (obj !== null && (typeof obj === 'object' || typeof obj === 'function')) { objectHooksMap.get(property).forEach(({ remaining, fn }) => { let ref = obj; try { for (let i = 0; i < remaining.length - 1; i++) { ref = ref[remaining[i]]; if (!ref) return; } ref[remaining[remaining.length - 1]] = fn; } catch (e) {} }); } return obj; } } const value = Reflect.get(target, property, target); if (typeof value === 'function') { return value.bind(target); } return value; }, }); return iframe_window; } }); } catch (e) { console.error('AntiAnti_Hook: 初始化失败', e); } } initAntiAntiHook(); })();Upvote 11 replies 但是还是会有问题，不完美 安装在油猴 打开F12 立马页面关了 统一回复一下师傅们，可能是检测机制又更新了，等我过两天或者考完试再改一下脚本~ 目前测试了，不会回退到空白页 现在playwright或者chrome-devtool似乎都又会回退了 You can't vote on a locked discussion 1 reply This comment was marked as disruptive content.Show comment Hide comment 请不要在我这里蹭流量推广你的项目好吗？ Upvote 0 replies You can't vote on 